package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
)

var encryptionKey []byte
var s3Client *s3.S3
var bucketName string

func init() {
	encryptionKey = []byte(os.Getenv("AES_KEY")) // 32 bytes for AES-256
	bucketName = os.Getenv("CONFIG_BUCKET")
	sess := session.Must(session.NewSession())
	s3Client = s3.New(sess)
}

// decryptCBC decrypts AES-CBC ciphertext with PKCS7 padding
func decryptCBC(ciphertextB64 string) ([]byte, error) {
	ciphertext, err := base64.StdEncoding.DecodeString(ciphertextB64)
	if err != nil {
		return nil, fmt.Errorf("base64 decode error")
	}

	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, fmt.Errorf("cipher error")
	}

	if len(ciphertext) < aes.BlockSize {
		return nil, fmt.Errorf("ciphertext too short")
	}

	iv := ciphertext[:aes.BlockSize]
	ciphertext = ciphertext[aes.BlockSize:]

	if len(ciphertext)%aes.BlockSize != 0 {
		return nil, fmt.Errorf("ciphertext not block aligned")
	}

	mode := cipher.NewCBCDecrypter(block, iv)
	mode.CryptBlocks(ciphertext, ciphertext)

	// PKCS7 unpadding - VULNERABLE: leaks padding validity via distinct errors
	padLen := int(ciphertext[len(ciphertext)-1])
	if padLen == 0 || padLen > aes.BlockSize {
		return nil, fmt.Errorf("invalid padding length")
	}
	for i := 0; i < padLen; i++ {
		if ciphertext[len(ciphertext)-1-i] != byte(padLen) {
			return nil, fmt.Errorf("invalid padding byte")
		}
	}

	return ciphertext[:len(ciphertext)-padLen], nil
}

// handleDecrypt processes encrypted session tokens and fetches user config from S3
func handleDecrypt(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "read error", http.StatusBadRequest)
		return
	}

	var req struct {
		Token string `json:"token"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		http.Error(w, "json parse error", http.StatusBadRequest)
		return
	}

	plaintext, err := decryptCBC(req.Token)
	if err != nil {
		// VULNERABILITY: Different error messages for padding vs other errors
		// enables padding oracle attack
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Use decrypted token as S3 key to fetch user configuration
	userKey := string(plaintext)
	result, err := s3Client.GetObject(&s3.GetObjectInput{
		Bucket: aws.String(bucketName),
		Key:    aws.String(fmt.Sprintf("configs/%s.json", userKey)),
	})
	if err != nil {
		http.Error(w, "config not found", http.StatusNotFound)
		return
	}
	defer result.Body.Close()

	configData, _ := ioutil.ReadAll(result.Body)
	w.Header().Set("Content-Type", "application/json")
	w.Write(configData)
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	http.HandleFunc("/api/v1/decrypt", handleDecrypt)
	http.HandleFunc("/health", handleHealth)
	fmt.Println("Starting server on :8080")
	http.ListenAndServe(":8080", nil)
}
